def main():
    try:
        payload = json.loads(sys.stdin.read())
    except ValueError:
        payload = None
    key = json.dumps(payload, sort_keys=True)
    if key not in TABLE:
        sys.stderr.write("invalid_input: input not in table\n")
        return 1
    answer = TABLE[key]
    if answer is None:
        sys.stderr.write("invalid_input: table refusal\n")
        return 1
    sys.stdout.write(json.dumps(answer, sort_keys=True) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
